<?php
require_once __DIR__ . '/../includes/auth.php';require_role(['superadmin']);$q=trim($_GET['q']??'');$sql="SELECT id,full_name,username,course_program,student_id,role,account_status,created_at,last_login_at FROM accounts";$args=[];if($q!==''){$sql.=" WHERE full_name LIKE ? OR username LIKE ? OR student_id LIKE ?";$args=["%$q%","%$q%","%$q%"];}$sql.=" ORDER BY created_at DESC";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();page_header('Manage Accounts');?><h1>Manage Accounts</h1><p><a class="btn" href="create-account.php">+ Create Account</a></p><form class="toolbar"><input name="q" value="<?=e($q)?>" placeholder="Search name, username, student ID"><button>Search</button></form><div class="table-wrap"><table><tr><th>ID</th><th>Name</th><th>Username</th><th>Role</th><th>Program</th><th>Student ID</th><th>Status</th><th>Created</th><th>Last Login</th><th>Edit</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><?=e($r['course_program'])?></td><td><?=e($r['student_id'])?></td><td><?=e($r['account_status'])?></td><td><?=e($r['created_at'])?></td><td><?=e($r['last_login_at']??'Never')?></td><td><a href="edit-account.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php page_footer();?>
